import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("Quote — basics", () => {
    it("empty item list → premium 5 G (only the processing fee)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [] }],
      });
      expect(result.results[0].premium).toBe(5);
    });
    it("single plain sword, newcomer, first insurance → premium 115 G (100 base + 10 first insurance = 110 + 5 fee = 115)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
          },
        ],
      });
      expect(result.results[0].premium).toBe(115);
    });
    it("single plain amulet, no modifiers besides first insurance → base 60 G + 10% first insurance + 5 fee = 71 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }],
          },
        ],
      });
      expect(result.results[0].premium).toBe(71);
    });
    it.todo("single staff base premium 80 G");
    it.todo("single potion base premium 40 G");
  });

  describe("Quote — components and building blocks", () => {
    it.todo("2 runes → 60 G base premium (2×25, no block)");
    it.todo("3 runes → 60 G base premium (block applies)");
    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
    it.todo("7 runes → 175 G base premium");
    it.todo('2 runes + 1 moonstone → 75 G base premium (no block: different types)');
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
  });

  describe("Quote — item-specific modifiers", () => {
    it.todo("cursed item adds 50% risk surcharge on that item's base premium");
    it.todo("highly enchanted item (enchantment >= 5) adds 30% risk surcharge on that item's base premium");
    it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge");
    it.todo("sword with enchantment 5 and cursed → both surcharges apply");
  });

  describe("Quote — policy-wide modifiers and scope", () => {
    it.todo(
      "policy with cursed sword (100 G base) + plain amulet (60 G base) → policy base 160 G; curse surcharge 50 G (50% of cursed item's base, not policy total) → 210 G before further modifiers and fee"
    );
    it.todo("customer with exactly 2 years with MHPCO → loyalty discount (20%) applies");
    it.todo("customer with 1 year with MHPCO → loyalty discount does not apply");
    it.todo("first quote in scenario → 10% first insurance surcharge applies to policy");
    it.todo("second quote in scenario for same customer → 15% follow-up contract discount applies to policy");
  });

  describe("Quote — rounding", () => {
    it.todo("a premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
    it.todo("intermediate amounts are kept as fractions; only final premium is rounded");
  });

  describe("Quote — integration examples", () => {
    it.todo(
      "newcomer (0 years, no previous contract) with cursed sword (steel, enchantment 3) → premium 165 G (100 base + 50 curse + 10 first insurance = 160 + 5 fee = 165)"
    );
    it.todo(
      "long-standing customer (3 years), second quote in scenario, cursed sword (steel, enchantment 7) → premium 160 G (100 base + 50 curse + 30 high enchantment - 20 loyalty + 10 first insurance - 15 follow-up = 155 + 5 fee = 160); first insurance surcharge still applies per item regardless of customer history"
    );
  });

  describe("Quote — error cases", () => {
    it.todo("quote includes an item with unknown type (e.g. broomstick) → CLI exits non-zero, writes error to stderr, no results to stdout");
  });

  describe("Claim — cap and insurance sum", () => {
    it.todo("policy with sword + amulet → insurance sum 1600 G (1000+600), cap 3200 G");
    it.todo("policy with two swords → insurance sum 2000 G (2×1000), cap 4000 G");
    it.todo("policy with sword + 3 runes (a block) → insurance sum 1750 G (1000 + 3×250); block discount affects premium only, not insurance sum");
    it.todo("cursed sword (insurance value 1000 G, premium with modifiers 165 G) → cap 2000 G (based on unmodified insurance value; premium modifiers do not raise the cap)");
  });

  describe("Claim — standard reimbursement", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G (full reimbursement minus 100 G deductible; no special clause)");
    it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G (full reimbursement minus 100 G deductible; runes have no enchantment/material, no special clause)");
  });

  describe("Claim — special clauses", () => {
    it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G (high-enchantment clause applies: 50% first, then deductible)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (both clauses apply; 50% rule wins, then deductible: 500 − 100)");
    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (only dragon-material clause applies: full reimbursement, then deductible: 800 − 100)");
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (only high-enchantment clause applies: 50% first, then deductible: 500 − 100)");
  });

  describe("Claim — deductible per damage event", () => {
    it.todo(
      "dragon attack damages an insured sword (500 G) and an insured amulet (300 G) → payout 600 G (100 G deductible applies once per damaged item)"
    );
    it.todo("two swords insured; damages array contains two separate sword damage entries → each entry treated as a separate damage with its own deductible");
  });

  describe("Claim — cap exhaustion across successive claims", () => {
    it.todo(
      "sword insured (insurance sum 1000 G, cap 2000 G); first claim of 1500 G → payout 1400 G, remainingCap 600 G"
    );
    it.todo(
      "same policy, second claim of 1500 G after first → payout 600 G, remainingCap 0 G (desired 1400 G reduced to remaining cap)"
    );
  });

  describe("Claim — rounding", () => {
    it.todo("a payout calculation yielding 350.5 G → final payout 350 G (rounded down)");
  });

  describe("Claim — error cases", () => {
    it.todo("claim references a damage entry whose item is not part of the policy (e.g. amulet damaged when only a sword is insured) → CLI exits non-zero, writes error to stderr");
    it.todo("claim references a damage entry with an unknown item type → CLI exits non-zero, writes error to stderr");
    it.todo("damages array contains more entries of a given type than the policy actually covers (e.g. two sword damages but only one sword insured) → CLI exits non-zero, whole claim rejected");
    it.todo("claim contains a damage entry with amount: -200 → CLI exits non-zero, writes error to stderr");
  });

  describe("CLI — end-to-end schema", () => {
    it.todo("schema example from spec: single amulet quote then claim → results array matches {premium} then {payout, remainingCap} shape");
    it.todo("results array has same length and order as input steps array");
  });
});

