const groupByType = (items) => {                    // binding groupByType(1), binding groups(1), binding items(param,1)
  const groups = {};                                  // constant {} (1)
  for (const item of items) {                         // loop(5), binding item(1)
    (groups[item.type] ??= []).push(item);             // assignment(6), invocation lookup(2), invocation push(2), constant [](1)
  }
  return groups;
};

const isPricedAsBlock = (type, count) =>              // binding(1), bindings type,count(2)
  count === BLOCK_SIZE && type in BLOCK_PRICE;         // conditional-as-expression(4), constant BLOCK_SIZE(1), invocation "in"(2)

const priceGroup = (type, items) =>                   // binding(1), bindings type,items(2)
  isPricedAsBlock(type, items.length)                  // invocation(2), invocation .length(2)
    ? BLOCK_PRICE[type]                                // conditional ?:(4), invocation lookup(2)
    : items.length * BASE_PREMIUM_BY_TYPE[type];        // invocation .length(2), invocation lookup(2)

export const runScenario = (scenario) => {
  const step = scenario.steps[0];                      // binding(1), invocation lookup(2), constant 0(1)
  const groupsByType = groupByType(step.items);         // binding(1), invocation(2)
  const basePremium = Object.entries(groupsByType).reduce( // binding(1), invocation entries(2), invocation reduce(2)
    (sum, [type, items]) => sum + priceGroup(type, items), // bindings sum,type,items(3), invocation priceGroup(2)
    0                                                    // constant(1)
  );
  const withFirstInsurance = basePremium + (basePremium * FIRST_INSURANCE_SURCHARGE_PERCENT) / 100; // binding(1), constant 100(1)
  const premium = Math.ceil(withFirstInsurance + PROCESSING_FEE); // binding(1), invocation ceil(2)
  return { results: [{ premium }] };                    // invocation obj-literal n/a
};
