  rune: 25,
  moonstone: 25,
};

const BLOCK_SIZE = 3;
const BLOCK_PRICE: Record<string, number> = {
  rune: 60,
  moonstone: 60,
};

const groupByType = (items: any[]): Record<string, any[]> => {
  const groups: Record<string, any[]> = {};
  for (const item of items) {
    (groups[item.type] ??= []).push(item);
  }
  return groups;
};

const isPricedAsBlock = (type: string, count: number): boolean =>
  count === BLOCK_SIZE && type in BLOCK_PRICE;

const priceGroup = (type: string, items: any[]): number =>
