const LOYALTY_DISCOUNT_PERCENT = 20;

const applySurcharge = (amount: number, percent: number): number =>
  amount + (amount * percent) / 100;

const applyDiscount = (amount: number, percent: number): number =>
  amount - (amount * percent) / 100;

export const runScenario = (scenario: any): { results: unknown[] } => {
  const step = scenario.steps[0];
  const groupsByType = groupByType(step.items);
  const basePremium = Object.entries(groupsByType).reduce(
    (sum, [type, items]) => sum + priceGroup(type, items),
    0
  );
  const itemSurcharge = step.items.reduce((sum: number, item: any) => {
    const itemBasePremium = BASE_PREMIUM_BY_TYPE[item.type];
    const surchargePercent =
      (item.cursed ? CURSE_SURCHARGE_PERCENT : 0) +
      (item.enchantment >= HIGH_ENCHANTMENT_THRESHOLD ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0);
    return sum + (itemBasePremium * surchargePercent) / 100;
  }, 0);
  const basePremiumWithItemModifiers = basePremium + itemSurcharge;
  const isLoyalCustomer = scenario.customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
  const withLoyalty = isLoyalCustomer
    ? applyDiscount(basePremiumWithItemModifiers, LOYALTY_DISCOUNT_PERCENT)
    : basePremiumWithItemModifiers;
  const withFirstInsurance = applySurcharge(withLoyalty, FIRST_INSURANCE_SURCHARGE_PERCENT);
  const premium = Math.ceil(withFirstInsurance + PROCESSING_FEE);
  return { results: [{ premium }] };
