const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const BLOCK_SIZE = 3;
const BLOCK_PRICE: Record<string, number> = {
  rune: 60,
  moonstone: 60,
};

const groupByType = (items: any[]): Record<string, any[]> => {
  const groups: Record<string, any[]> = {};
  for (const item of items) {
    (groups[item.type] ??= []).push(item);
  }
  return groups;
};

const isPricedAsBlock = (type: string, count: number): boolean =>
  count === BLOCK_SIZE && type in BLOCK_PRICE;

const priceGroup = (type: string, items: any[]): number =>
  isPricedAsBlock(type, items.length)
    ? BLOCK_PRICE[type]
    : items.length * BASE_PREMIUM_BY_TYPE[type];

const CURSE_SURCHARGE_PERCENT = 50;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
const LOYALTY_YEARS_THRESHOLD = 2;
const LOYALTY_DISCOUNT_PERCENT = 20;
const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;

const quotePremium = (
  step: any,
  customer: any,
  isFollowUpContract: boolean
): number => {
  const groupsByType = groupByType(step.items);
  const basePremium = Object.entries(groupsByType).reduce(
    (sum, [type, items]) => sum + priceGroup(type, items),
    0
  );
  const itemSurcharge = step.items.reduce((sum: number, item: any) => {
    const itemBasePremium = BASE_PREMIUM_BY_TYPE[item.type];
    const surchargePercent =
      (item.cursed ? CURSE_SURCHARGE_PERCENT : 0) +
      (item.enchantment >= HIGH_ENCHANTMENT_THRESHOLD ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0);
    return sum + (itemBasePremium * surchargePercent) / 100;
  }, 0);
  const isLoyalCustomer = customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
  const policyModifierPercent =
    FIRST_INSURANCE_SURCHARGE_PERCENT +
    (isLoyalCustomer ? -LOYALTY_DISCOUNT_PERCENT : 0) +
    (isFollowUpContract ? -FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT : 0);
  const policyModifierAmount = (basePremium * policyModifierPercent) / 100;
  const premiumBeforeFee = basePremium + itemSurcharge + policyModifierAmount;
  return Math.ceil(premiumBeforeFee + PROCESSING_FEE);
};

export const runScenario = (scenario: any): { results: unknown[] } => {
  const results = scenario.steps.map((step: any, index: number) => {
    const isFollowUpContract = index > 0;
    return { premium: quotePremium(step, scenario.customer, isFollowUpContract) };
  });
  return { results };
};

